    public sealed partial class SnowmanMatch:SportsEventSession,ISportsWorkshopState
    {
        public SportsEventTruck[] trucks;public SnowmanBall[] balls;public SnowmanSnowPatch[] patches;public SnowmanDecorFamily[] decorations;
        public Transform buildCenter,supply;public Collider foundation;public Rigidbody foundationBody;public JengaCrane hoist;public SportsEventCamera broadcast;public SportsDrivingViews drivingViews;public Animator[] spectators;
        public SnowmanCollectionRack collectionRack;
        public SnowmanRules Rules {get;private set;}public float Clock {get;private set;}public int LiftRole {get;private set;}=-1;public float Stable {get;private set;}public bool Gallery {get;private set;}
        public string RestoredSourceMatchId {get;private set;}="";
        readonly int[] work={0,1,2,-1},family={0,1,2,3},style=new int[4],carried={-1,-1,-1,-1},carriedStyle=new int[4],installedStyle=new int[6];readonly float[] nav=new float[4];
        readonly GameObject[] cargo=new GameObject[4],installed=new GameObject[6];readonly Tween[] placements=new Tween[4];Vector3[] seeds;float finishAge;bool decorationInterrupted;
        public override string Title=>"TRUCK SNOWMAN BUILDING";public override int MinimumPlayers=>1;public override int MaximumPlayers=>4;public override int OptionCount=>1;public override string OptionLabel=>"COOPERATIVE WINTER WORKSHOP";
        public override string Help=>"PHYSICAL COLLECTION RACK: Roll each grown sphere down its marked lane into the open-front timber catch. Real planks stop it; leave it to settle before requesting the original hoist. The open top provides real crane clearance. No automatic score or snapping occurs in this rack.\n\nBuild one giant snowman together. Physically push the three snow seeds down the marked loose-snow lanes. Snow grows only from real grounded rolling; spinning in place, sliding without rotation and flying collect none. Snow patches have finite supplies. Suggested base/middle/head sizes are 2.4 / 1.7 / 1.2 m radius; different drift depths help proportions. Deliver each ball to the marked collection forecourt. ACTION requests the village hoist when the next ball is large enough and physically delivered. It lifts the dynamic ball, then releases it into actual ground or sphere contact. Only aligned, slow contact packs the snow at its measured pose; nothing snaps into place.\nAfter all three balls are packed, drive to the decoration cabinet. At low speed, steering selects item, throttle/brake selects style; ACTION picks it up. Drive near the statue and ACTION animates its placement. Choose carrot, coal face, scarf, hat, stick arms and a novelty toy. You can change a style before finishing. ACTION empty-handed near the finished stable snowman, or FINISH in the HUD, completes the build. Team grade rewards measured height, proportions, stability, decoration and completion time. All helpers use actual physics/actions. Save/restore uses the shared workshop adapter at stopped/paused stable boundaries; ongoing hoist or decoration motion must finish first. Saved completed designs reopen as galleries without another score.";
        public override bool SupportsSplitAIViews=>true;public override bool CompactBroadcastStatus=>true;public override bool CompactViewportHud=>true;public override int CompactScoreColumns=>1;public override int ScoreCardCount=>1;public override string ScoreCardLabel(int card)=>"BUILD CREW";public override int ScoreCardSource(int card)=>0;public override Color ScoreCardColor(int card)=>new Color(.3f,.85f,1);
        public override bool MultiViewHUD=>drivingViews!=null&&!drivingViews.NeedsArena;
        public override string Header=>Gallery?"SAVED SCULPTURE GALLERY":Rules==null?Title:$"CREW BUILD · {Rules.Placed}/3 PACKED · {CountDecor()}/6 DECORATED";
        public override string Status=>Rules==null?"":LiftRole>=0?"HOIST · "+hoist.Stage:Rules.Placed<3?"ROLL INTO THE MARKED COLLECTION RACK / PHYSICAL HOIST":"DECORATE · "+Choice(Enumerable.Range(0,setup.count).Where(i=>setup.players[i].source!=BowlingSource.AI).DefaultIfEmpty(0).First())+" · "+Clock.ToString("0.0")+"s";
        public override string Standings=>Rules==null?"":string.Join("\n",Enumerable.Range(0,setup.count).Select(i=>setup.players[i].name+" · "+(carried[i]>=0?decorations[carried[i]].label:work[i]>=0?"ROLLING "+new[]{"BASE","MIDDLE","HEAD"}[work[i]]:"DECORATOR")));
        public override string Results=>Rules==null?"":"WINTER WORKSHOP COMPLETE\nTEAM GRADE "+Rules.Score+"\nHEIGHT "+Height.ToString("0.0")+"m · "+Clock.ToString("0.0")+"s\n"+Standings;
        public override bool TryReadScoreCard(int card,out string value,out string detail){value=Rules==null?"0":Rules.Complete?Rules.Score.ToString():Rules.Placed+"/3";detail=Rules!=null&&Rules.Complete?"TEAM GRADE":"PACKED · "+CountDecor()+"/6 DECOR";return card==0;}
        public override bool TryReadViewportCard(int view,out int participant,out string score,out string detail){participant=drivingViews!=null&&view>=0&&view<drivingViews.rally.owners.Length?drivingViews.rally.owners[view]:-1;score=Rules!=null?Rules.Placed+"/3":"0/3";detail=participant>=0&&participant<4&&carried[participant]>=0?decorations[carried[participant]].label:"CREW BUILD";return participant>=0&&participant<setup.count;}
        public override string ViewportContextPrompt(int view)=>Status;public override string ViewportTelemetry(int view){int owner=drivingViews!=null&&view>=0&&view<drivingViews.rally.owners.Length?drivingViews.rally.owners[view]:0;return $"HEIGHT {Height:0.0}m | {Clock:0.0}s"+(owner>=0&&owner<setup.count&&Rules!=null&&Rules.Placed==3?" | "+Choice(owner):"");}
        string Choice(int owner)=>carried[owner]>=0?"CARRYING "+decorations[carried[owner]].label:decorations[family[owner]].label+" STYLE "+(style[owner]+1)+"/"+decorations[family[owner]].variants.Length;
        public override void DescribeBroadcast(SportsBroadcastAction action,SportsBroadcastFraming framing){if(Rules==null)return;action.primary=0;action.reason="ROLLING / COOPERATIVE SNOWMAN";int role=LiftRole>=0?LiftRole:Mathf.Min(2,Rules.Placed);action.Objective(balls[role].body.position,balls[role].radius+1);}
        public float Height=>balls==null||balls.Length!=3||Rules==null||Rules.Placed==0?0:Mathf.Max(0,balls[Rules.Placed-1].body.position.y+balls[Rules.Placed-1].radius-(balls[0].body.position.y-balls[0].radius));
        int CountDecor(){int n=0;if(Rules!=null)for(int i=0;i<6;i++)if((Rules.Decorations&(1<<i))!=0)n++;return n;}
        protected override void BeginGame(){if(balls.Length!=3||trucks.Length!=4||decorations.Length!=6||collectionRack==null||collectionRack.match!=this)throw new InvalidOperationException("Full winter workshop authoring is required.");Rules=new SnowmanRules();collectionRack.ResetContacts();ResetAiDelivery();ResetAiDecorating();Clock=Stable=finishAge=0;Gallery=false;decorationInterrupted=false;RestoredSourceMatchId="";LiftRole=-1;hoist.ResetCrane();ClearDecor();foreach(var patch in patches)patch.ResetSnow();if(seeds==null)seeds=new[]{new Vector3(-10,.75f,-80),new Vector3(0,.75f,-80),new Vector3(10,.75f,-80)};for(int b=0;b<3;b++)balls[b].ResetBall(seeds[b]);for(int i=0;i<4;i++){work[i]=i<3?i:-1;family[i]=i;style[i]=0;nav[i]=0;trucks[i].gameObject.SetActive(i<setup.count);if(i<setup.count){trucks[i].tractorMotor.Configure();trucks[i].Prepare(i<3?new Vector3((i-1)*10,.7f,-87):new Vector3(27,.7f,-12),Quaternion.identity);}}if(drivingViews!=null)drivingViews.Layout();ApplyStoppedRestoreAtStart();}
        public bool RequestLift(){if(!Live||Gallery||LiftRole>=0||Rules.Placed>=3)return false;int role=Rules.Placed;var ball=balls[role];float[] minimum={1.8f,1.2f,.85f};if(ball.radius<minimum[role]||ball.Rolled<8||Mathf.Abs(ball.body.position.x)>17||ball.body.position.z< -11||ball.body.position.z>5||ball.body.linearVelocity.magnitude>.7f)return false;Vector3 target=role==0?buildCenter.position+Vector3.up*ball.radius:balls[role-1].body.position+Vector3.up*(balls[role-1].radius+ball.radius);if(!hoist.Begin(ball.body,target,Quaternion.identity,ball.radius*2))return false;LiftRole=role;return true;}
        public bool PickDecoration(int owner){if(!Live||Gallery||Rules.Placed!=3||owner<0||owner>=setup.count||carried[owner]>=0||Vector3.Distance(trucks[owner].body.position,supply.position)>7)return false;int f=family[owner],v=style[owner]%decorations[f].variants.Length;cargo[owner]=Instantiate(decorations[f].variants[v],trucks[owner].transform,false);cargo[owner].SetActive(true);cargo[owner].transform.localPosition=new Vector3(0,2.7f,0);cargo[owner].transform.localScale*=.55f;carried[owner]=f;carriedStyle[owner]=v;return true;}
        public bool PlaceDecoration(int owner){if(!Live||Gallery||carried[owner]<0||Vector3.Distance(trucks[owner].body.position,buildCenter.position)>10.5f||placements[owner]!=null)return false;int f=carried[owner],v=carriedStyle[owner];var item=cargo[owner];item.transform.SetParent(null,true);Vector3 target=Mount(f);placements[owner]=item.transform.DOPath(new[]{item.transform.position+Vector3.up*3,target+Vector3.up*2,target},1.4f,DG.Tweening.PathType.CatmullRom).SetEase(Ease.InOutSine).OnComplete(()=>{if(installed[f]!=null)Destroy(installed[f]);installed[f]=item;installedStyle[f]=v;PoseDecoration(item,f);Rules.Decorate(f,true);carried[owner]=-1;cargo[owner]=null;placements[owner]=null;feedback.Play(2,0,true);}).SetLink(gameObject);return true;}
        Vector3 Mount(int f){var head=balls[2];var middle=balls[1];return f==0?head.body.position+Vector3.back*(head.radius+.05f):f==1?head.body.position:f==2?middle.body.position+Vector3.up*(middle.radius*.55f):f==3?head.body.position+Vector3.up*head.radius:f==4?middle.body.position:head.body.position+Vector3.up*(head.radius+1.2f);}
        void PoseDecoration(GameObject item,int f){item.transform.SetParent((f==2||f==4?balls[1]:balls[2]).transform,true);item.transform.SetPositionAndRotation(Mount(f),Quaternion.identity);item.transform.localScale=Vector3.one*(f==0?balls[2].radius*.8f:f==1||f==3?balls[2].radius:f==2||f==4?balls[1].radius:balls[2].radius*.75f);item.SetActive(true);}
        public bool FinishBuild(){if(!Live||Gallery||Stable<2)return false;float offset=Vector3.ProjectOnPlane(balls[1].body.position-balls[0].body.position,Vector3.up).magnitude+Vector3.ProjectOnPlane(balls[2].body.position-balls[1].body.position,Vector3.up).magnitude;float rating=Mathf.Clamp01(1-offset/Mathf.Max(.1f,balls[0].radius*.5f));if(!Rules.Finish(true,Height,balls[0].radius,balls[1].radius,balls[2].radius,rating,Clock))return false;ConfirmTeamScore("snowman.completed","snowman.crew","WINTER BUILD CREW",new Color(.3f,.85f,1),Rules.Score,Rules.Score,"MEASURED SNOWMAN",SportsScoreTier.MatchChampion,"PTS",matchEnded:true);foreach(var fan in spectators)if(fan!=null)fan.CrossFade("Cheer",.2f);finishAge=0;return true;}
        protected override void Simulate(float dt){if(Gallery)return;if(Rules.Complete){finishAge+=dt;if(finishAge>2.5f)EndMatch();return;}Clock+=dt;foreach(var ball in balls)ball.Step();if(LiftRole>=0){int role=LiftRole;hoist.Step(dt,Rules.Placed==0?0:balls[Rules.Placed-1].body.position.y+balls[Rules.Placed-1].radius);var ball=balls[role];Vector3 target=role==0?buildCenter.position+Vector3.up*ball.radius:balls[role-1].body.position+Vector3.up*(balls[role-1].radius+ball.radius);bool atRest=hoist.AtRest(target,ball.radius*2);if(!atRest)ball.CancelRest();if(atRest&&ball.RestOn(role>0?balls[role-1]:null,foundation,dt)&&Rules.Place(role,true)){ball.Pack(role>0?balls[role-1]:null);hoist.Complete();LiftRole=-1;feedback.Play(4,0,true);}}bool steady=Rules.Placed==3&&balls.All(b=>b.Packed&&b.body.linearVelocity.magnitude<.15f&&b.body.angularVelocity.magnitude<.15f);Stable=steady?Stable+dt:0;
            for(int i=0;i<setup.count;i++){nav[i]-=dt;bool ai=setup.players[i].source==BowlingSource.AI;Vector2 drive=commands[i];if(ai){if(Rules.Placed<3){if(work[i]<0||balls[work[i]].Packed){work[i]=Enumerable.Range(0,3).Where(r=>!balls[r].Packed&&!work.Where((w,slot)=>slot!=i&&slot<setup.count).Contains(r)).DefaultIfEmpty(-1).First();if(work[i]>=0&&balls[work[i]].Packed)work[i]=-1;}if(work[i]>=0){var b=balls[work[i]];drive=DeliverRollingBall(i,work[i]);}else drive=new Vector2(0,-1);}
                    else drive=DecorateWithOriginalTruck(i);}
                else{if(Rules.Placed<3){if(actions[i])RequestLift();}else{bool near=Vector3.Distance(trucks[i].body.position,supply.position)<7&&trucks[i].body.linearVelocity.magnitude<.7f;if(near&&carried[i]<0&&nav[i]<=0){if(Mathf.Abs(drive.x)>.5f){family[i]=(family[i]+(drive.x>0?1:5))%6;style[i]=0;nav[i]=.3f;}else if(Mathf.Abs(drive.y)>.5f){style[i]=(style[i]+1)%decorations[family[i]].variants.Length;nav[i]=.4f;}}if(actions[i]){if(carried[i]>=0)PlaceDecoration(i);else if(near)PickDecoration(i);else if(Vector3.Distance(trucks[i].body.position,buildCenter.position)<=10.5f)FinishBuild();}}}if(ai&&Mathf.Abs(drive.x)<.001f&&drive.y<=-.99f)AiPark(i);else trucks[i].TickDrive(drive);}}
        static Vector2 DriveTo(SportsEventTruck truck,Vector3 target,float speed)
        {
            Vector3 d=Vector3.ProjectOnPlane(target-truck.body.position,Vector3.up);if(d.magnitude<1.3f)return new Vector2(0,-1);
            float angle=Vector3.SignedAngle(Vector3.ProjectOnPlane(truck.transform.forward,Vector3.up),d,Vector3.up);bool reverse=Mathf.Abs(angle)>105;
            float error=reverse?Mathf.DeltaAngle(180,angle):angle;float desired=Mathf.Min(speed,d.magnitude*.65f);float along=Vector3.Dot(truck.body.linearVelocity,truck.transform.forward)*(reverse?-1:1);
            float effort=Mathf.Clamp((desired-along)*.6f,-.8f,.8f);return new Vector2(Mathf.Clamp(error/30,-1,1)*(reverse?-1:1),effort*(reverse?-1:1));
        }
        public override void ExtraAction(string key){if(key=="drivingview"&&drivingViews!=null){drivingViews.Cycle();return;}if(!Live)return;int owner=Enumerable.Range(0,setup.count).Where(i=>setup.players[i].source!=BowlingSource.AI).DefaultIfEmpty(-1).First();if(owner<0)return;if(key=="snowman.lift")RequestLift();else if(key=="snowman.finish")FinishBuild();else if(key=="snowman.family"){family[owner]=(family[owner]+1)%6;style[owner]=0;}else if(key=="snowman.style")style[owner]=(style[owner]+1)%decorations[family[owner]].variants.Length;else if(key=="snowman.decorate"){if(carried[owner]>=0)PlaceDecoration(owner);else PickDecoration(owner);}}

        protected override void Present(float dt){if(drivingViews!=null)drivingViews.Tick(dt);if(hoist!=null)hoist.Present();if(broadcast!=null&&(drivingViews==null||drivingViews.NeedsArena)){Vector3 focus=Rules==null?buildCenter.position:Rules.Placed==3?buildCenter.position+Vector3.up*4:balls[Mathf.Min(2,Rules.Placed)].body.position;broadcast.Pose(focus,new Vector3(24,25,-32),58);}foreach(var fan in spectators)if(fan!=null)fan.speed=Live&&!Gallery?1:0;}
        void ClearDecor(){for(int i=0;i<4;i++){if(placements[i]!=null)placements[i].Kill();placements[i]=null;if(cargo[i]!=null)Destroy(cargo[i]);cargo[i]=null;carried[i]=-1;}for(int f=0;f<6;f++){if(installed[f]!=null)Destroy(installed[f]);installed[f]=null;installedStyle[f]=0;}}
        protected override void StopGame(){if(hoist!=null)hoist.StopCrane();foreach(var truck in trucks??Array.Empty<SportsEventTruck>())if(truck!=null)truck.Power(false);for(int i=0;i<4;i++)if(placements[i]!=null){decorationInterrupted=true;placements[i].Kill();placements[i]=null;}}
        protected override void StopSounds(){foreach(var truck in trucks??Array.Empty<SportsEventTruck>())if(truck!=null)truck.StopSound();}
    }
